import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.Cx-5KwGw.js";const u=JSON.parse('{"title":"添加开机脚本","description":"","frontmatter":{"title":"添加开机脚本","author":"麻瓜【码瓜】","date":"2024-07-30"},"headers":[],"relativePath":"posts/linux/startup.md","filePath":"posts/linux/startup.md"}'),p={name:"posts/linux/startup.md"};function i(l,a,c,o,r,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="添加开机脚本" tabindex="-1">添加开机脚本 <a class="header-anchor" href="#添加开机脚本" aria-label="Permalink to &quot;添加开机脚本&quot;">​</a></h1><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>网上很多都采用init.d或者rc.local来制作开机脚本，经过实验以上两种都比较麻烦，本文采用目前Ubuntu默认支持的systermd方式添加开机启动脚本</p><h2 id="过程" tabindex="-1">过程 <a class="header-anchor" href="#过程" aria-label="Permalink to &quot;过程&quot;">​</a></h2><h3 id="制作service文件" tabindex="-1">制作service文件 <a class="header-anchor" href="#制作service文件" aria-label="Permalink to &quot;制作service文件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim /usr/lib/systemd/system/startup.service</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=Startup Script</span></span>
<span class="line"><span>After=network.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=oneshot</span></span>
<span class="line"><span>ExecStart=/usr/local/etc/startup.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre></div><h3 id="制作-sh脚本文件" tabindex="-1">制作.sh脚本文件 <a class="header-anchor" href="#制作-sh脚本文件" aria-label="Permalink to &quot;制作.sh脚本文件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim /usr/local/etc/startup.sh</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ ! -f /root/service.txt ]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    echo \`date -R\` &gt; /root/service.txt</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    echo \`date -R\` &gt;&gt; /root/service.txt</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>赋予执行权限</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod +x /usr/local/etc/startup.sh</span></span></code></pre></div><h3 id="开机启动" tabindex="-1">开机启动 <a class="header-anchor" href="#开机启动" aria-label="Permalink to &quot;开机启动&quot;">​</a></h3><p>此步骤相当于将<code>/usr/lib/systemd/system/startup.sh</code>链接到<code>/etc/systemd/system/multi-user.target.wants/startup.service</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemctl enable startup.service</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemctl daemon-reload</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>此方法相对于其他方法更加简单方便，也是Ubuntu现在默认的添加开机启动的方案</p>`,18)])])}const b=s(p,[["render",i]]);export{u as __pageData,b as default};
